INSERT INTO public_competition_questions (question, options, answer, explanation, category, difficulty) VALUES
('What was the first thing God created?', ARRAY['Light', 'Earth', 'Animals', 'Man'], 'Light', 'Genesis 1:3 - Then God said, "Let there be light," and there was light.', 'Pentateuch', 'Easy'),
('On which day did God create man?', ARRAY['Fifth day', 'Sixth day', 'Seventh day', 'Fourth day'], 'Sixth day', 'Genesis 1:26-31 - God created man on the sixth day.', 'Pentateuch', 'Easy'),
('Who was the first man created by God?', ARRAY['Noah', 'Abraham', 'Adam', 'Seth'], 'Adam', 'Genesis 2:7 - Then the Lord God formed a man from the dust of the ground.', 'Pentateuch', 'Easy'),
('Who was Adam''s wife?', ARRAY['Sarah', 'Eve', 'Rebekah', 'Leah'], 'Eve', 'Genesis 2:22 - Then the Lord God made a woman from the rib he had taken out of the man.', 'Pentateuch', 'Easy'),
('What did God use to make Eve?', ARRAY['Dust', 'Water', 'Adam''s rib', 'A stone'], 'Adam''s rib', 'Genesis 2:22 - The Lord God made a woman from the rib he had taken out of the man.', 'Pentateuch', 'Easy'),
('In what garden did Adam and Eve live?', ARRAY['Garden of Gethsemane', 'Garden of Eden', 'Garden of Sharon', 'Garden of Zion'], 'Garden of Eden', 'Genesis 2:8 - Now the Lord God had planted a garden in the east, in Eden.', 'Pentateuch', 'Easy'),
('Who tempted Eve to eat the forbidden fruit?', ARRAY['A lion', 'A snake', 'An angel', 'Adam'], 'A snake', 'Genesis 3:1 - Now the serpent was more crafty than any of the wild animals.', 'Pentateuch', 'Easy'),
('Who were Adam and Eve''s first two sons?', ARRAY['Cain and Abel', 'Isaac and Ishmael', 'Jacob and Esau', 'Shem and Ham'], 'Cain and Abel', 'Genesis 4:1-2 - Eve gave birth to Cain and then his brother Abel.', 'Pentateuch', 'Easy'),
('Which brother killed the other in the first murder?', ARRAY['Abel killed Cain', 'Cain killed Abel', 'Seth killed Cain', 'Ham killed Shem'], 'Cain killed Abel', 'Genesis 4:8 - Cain attacked his brother Abel and killed him.', 'Pentateuch', 'Easy'),
('Who built an ark to survive the great flood?', ARRAY['Moses', 'Noah', 'Abraham', 'Enoch'], 'Noah', 'Genesis 6:13-14 - God said to Noah... "So make yourself an ark of cypress wood."', 'Pentateuch', 'Easy'),
('How many people were saved on the ark?', ARRAY['2', '4', '8', '12'], '8', '1 Peter 3:20 - ...In it only a few people, eight in all, were saved through water.', 'Pentateuch', 'Medium'),
('What was the sign of God''s covenant with Noah?', ARRAY['A burning bush', 'A rainbow', 'A pillar of salt', 'A golden calf'], 'A rainbow', 'Genesis 9:13 - I have set my rainbow in the clouds, and it will be the sign of the covenant.', 'Pentateuch', 'Easy'),
('What did the people build to try to reach heaven?', ARRAY['The Great Wall', 'The Temple of Solomon', 'The Tower of Babel', 'The Pyramids'], 'The Tower of Babel', 'Genesis 11:4 - "Come, let us build ourselves a city, with a tower that reaches to the heavens."', 'Pentateuch', 'Easy'),
('Who is known as the father of many nations?', ARRAY['Jacob', 'Isaac', 'Abraham', 'Joseph'], 'Abraham', 'Genesis 17:5 - No longer will you be called Abram; your name will be Abraham.', 'Pentateuch', 'Easy'),
('Who was Abraham''s wife?', ARRAY['Hagar', 'Sarah', 'Rachel', 'Rebekah'], 'Sarah', 'Genesis 17:15 - God also said to Abraham, "As for Sarai your wife... her name will be Sarah."', 'Pentateuch', 'Easy'),
('How old was Abraham when his son Isaac was born?', ARRAY['75', '100', '120', '90'], '100', 'Genesis 21:5 - Abraham was a hundred years old when his son Isaac was born.', 'Pentateuch', 'Hard'),
('Who was Isaac''s wife?', ARRAY['Leah', 'Rachel', 'Rebekah', 'Zipporah'], 'Rebekah', 'Genesis 24:67 - Isaac brought her into the tent... and she became his wife.', 'Pentateuch', 'Medium'),
('Who were the twin sons of Isaac and Rebekah?', ARRAY['Jacob and Esau', 'Ephraim and Manasseh', 'Cain and Abel', 'Joseph and Benjamin'], 'Jacob and Esau', 'Genesis 25:24-26 - The first to come out was red... then his brother came out.', 'Pentateuch', 'Medium'),
('Which son sold his birthright for a bowl of stew?', ARRAY['Jacob', 'Esau', 'Reuben', 'Joseph'], 'Esau', 'Genesis 25:33-34 - So he swore an oath to him, selling his birthright to Jacob.', 'Pentateuch', 'Medium'),
('Who had a dream of a ladder reaching to heaven?', ARRAY['Joseph', 'Jacob', 'Isaac', 'Abraham'], 'Jacob', 'Genesis 28:12 - He had a dream in which he saw a stairway resting on the earth.', 'Pentateuch', 'Medium'),
('How many sons did Jacob have?', ARRAY['10', '12', '7', '13'], '12', 'Genesis 35:22 - Jacob had twelve sons.', 'Pentateuch', 'Easy'),
('Who was Jacob''s favorite son?', ARRAY['Reuben', 'Judah', 'Joseph', 'Benjamin'], 'Joseph', 'Genesis 37:3 - Now Israel loved Joseph more than any of his other sons.', 'Pentateuch', 'Easy'),
('What did Joseph''s father give him that made his brothers jealous?', ARRAY['A gold ring', 'A flock of sheep', 'A coat of many colors', 'A silver cup'], 'A coat of many colors', 'Genesis 37:3 - ...he made an ornate robe for him.', 'Pentateuch', 'Easy'),
('Where did Joseph''s brothers sell him as a slave?', ARRAY['Assyria', 'Babylon', 'Egypt', 'Moab'], 'Egypt', 'Genesis 37:28 - ...and sold him for twenty shekels of silver to the Ishmaelites, who took him to Egypt.', 'Pentateuch', 'Easy'),
('Who interpreted Pharaoh''s dreams?', ARRAY['Moses', 'Joseph', 'Daniel', 'Aaron'], 'Joseph', 'Genesis 41:15-16 - Pharaoh said to Joseph... "I have heard it said of you that when you hear a dream you can interpret it."', 'Pentateuch', 'Medium'),
('In what basket was baby Moses placed in the Nile?', ARRAY['Wicker basket', 'Papyrus basket', 'Wooden box', 'Clay pot'], 'Papyrus basket', 'Exodus 2:3 - Then she got a papyrus basket for him and coated it with tar and pitch.', 'Pentateuch', 'Medium'),
('Who found baby Moses in the river?', ARRAY['Pharaoh''s daughter', 'A Hebrew slave', 'A shepherd', 'Pharaoh''s wife'], 'Pharaoh''s daughter', 'Exodus 2:5 - Pharaoh''s daughter went down to the Nile to bathe... She saw the basket.', 'Pentateuch', 'Easy'),
('From what did God speak to Moses in the desert?', ARRAY['A cloud', 'A burning bush', 'A mountain top', 'A whirlwind'], 'A burning bush', 'Exodus 3:2 - There the angel of the Lord appeared to him in flames of fire from within a bush.', 'Pentateuch', 'Easy'),
('What was the first plague God sent upon Egypt?', ARRAY['Frogs', 'Blood', 'Locusts', 'Darkness'], 'Blood', 'Exodus 7:20 - ...all the water in the Nile was changed into blood.', 'Pentateuch', 'Medium'),
('How many plagues did God send upon Egypt?', ARRAY['7', '10', '12', '40'], '10', 'Exodus 7-11 - The Bible records ten distinct plagues.', 'Pentateuch', 'Easy'),
('What sea did the Israelites cross to escape Egypt?', ARRAY['Mediterranean Sea', 'Dead Sea', 'Red Sea', 'Sea of Galilee'], 'Red Sea', 'Exodus 14:21 - ...and the Lord drove the sea back... and turned it into dry land.', 'Pentateuch', 'Easy'),
('What food did God provide from heaven for the Israelites in the desert?', ARRAY['Quail', 'Manna', 'Bread', 'Honey'], 'Manna', 'Exodus 16:31 - The people of Israel called the bread manna.', 'Pentateuch', 'Easy'),
('On what mountain did Moses receive the Ten Commandments?', ARRAY['Mount Nebo', 'Mount Sinai', 'Mount Carmel', 'Mount Hermon'], 'Mount Sinai', 'Exodus 19:20 - The Lord descended to the top of Mount Sinai and called Moses.', 'Pentateuch', 'Easy'),
